    # We will use a rolling array approach to save space: prev_dp[color][groups]
    # Colors are 1 to m. We'll map them to 0 to m-1 internally.

    # Initialize with infinity
    INF = float('inf')

    # prev_dp[color][groups]
    # color: 0 to m-1
    # groups: 0 to k
    prev_dp = [[INF] * (k + 1) for _ in range(m)]

    # Base case: first tree (index 0)
    first_tree_color = c[0]

    for color_idx in range(m):
        actual_color = color_idx + 1
        cost = 0

        if first_tree_color == 0:
            # Tree is uncolored, we can choose this color
            cost = p[0][color_idx]
        elif first_tree_color == actual_color:
            # Tree is already colored with this color
            cost = 0
        else:
            # Tree is colored with a different color, cannot choose this color
            continue

        # If we pick this color for the first tree, we have exactly 1 group
        if cost != INF:
            prev_dp[color_idx][1] = cost

    # If k=1 and we couldn't set any state (e.g., n=1 and constraints prevent it), handle later
    # But note: if n=1, we must have 1 group. If k=1, we are good. If k>1, impossible.

    for i in range(1, n):
        curr_dp = [[INF] * (k + 1) for _ in range(m)]
        current_tree_color = c[i]

        for color_idx in range(m):
            actual_color = color_idx + 1

            # Determine cost to color current tree with actual_color
            if current_tree_color == 0:
                cost = p[i][color_idx]
            elif current_tree_color == actual_color:
                cost = 0
            else:
                cost = INF # Cannot use this color

            if cost == INF:
                continue

            # Try all previous group counts
            for g in range(1, k + 1):
                if prev_dp[color_idx][g] == INF:
                    continue

                # Option 1: Same color as previous tree
                # Then group count remains g
                if curr_dp[color_idx][g] > prev_dp[color_idx][g] + cost:
                    curr_dp[color_idx][g] = prev_dp[color_idx][g] + cost

                # Option 2: Different color from previous tree
                # Then group count becomes g + 1
                if g + 1 <= k:
                    for prev_color_idx in range(m):
                        if prev_color_idx == color_idx:
                            continue
                        if prev_dp[prev_color_idx][g] == INF:
                            continue

                        new_cost = prev_dp[prev_color_idx][g] + cost
                        if curr_dp[color_idx][g + 1] > new_cost:
