                # Option 2: Extend the current group (only if g == 1 is not possible here unless i=1, but loop starts at 2)
                # Actually, if we extend, the group count doesn't increase.
                # So if current state has g groups, previous state must have had g groups.
                # This is valid for any g >= 1.
                if dp[i-1][new_color][g] != INF:
                    if dp[i-1][new_color][g] + cost < dp[i][new_color][g]:
                        dp[i][new_color][g] = dp[i-1][new_color][g] + cost

    # The answer is the minimum cost in dp[n][any_color][k]
    ans = INF
    for color in range(1, m + 1):
        if dp[n][color][k] < ans:
