        row = []
        for j in range(m):
            row.append(int(next(iterator)))
        p.append(row)

    # dp[j][g] = minimum cost to color up to current tree such that:
    # current tree has color j (1-based) and there are exactly g groups.
    # Initialize with infinity.
    INF = float('inf')

    # Previous state
    prev_dp = [[INF] * (k + 1) for _ in range(m + 1)]

    # Base case: first tree
    first_color = c[0]
    first_costs = p[0]

    for color in range(1, m + 1):
        if first_color != 0 and first_color != color:
            continue
        cost = 0
        if first_color == 0:
            cost = first_costs[color - 1]
        prev_dp[color][1] = cost

    # Iterate through the rest of the trees
    for i in range(1, n):
        curr_dp = [[INF] * (k + 1) for _ in range(m + 1)]
        current_fixed = c[i]
        current_costs = p[i]

        for g in range(1, k + 1):
            for new_color in range(1, m + 1):
                if current_fixed != 0 and current_fixed != new_color:
                    continue

                cost_add = 0
                if current_fixed == 0:
                    cost_add = current_costs[new_color - 1]

                # Try to transition from previous colors
                for prev_color in range(1, m + 1):
                    if prev_dp[prev_color][g] == INF:
                        continue

                    if prev_color == new_color:
                        # Same color, group count doesn't increase
                        curr_dp[new_color][g] = min(curr_dp[new_color][g], prev_dp[prev_color][g] + cost_add)
                    else:
                        # Different color, group count increases
                        if g > 1:
                            curr_dp[new_color][g] = min(curr_dp[new_color][g], prev_dp[prev_color][g - 1] + cost_add)

        prev_dp = curr_dp

    # Find the minimum cost for exactly k groups with any color
    ans = min(prev_dp[color][k] for color in range(1, m + 1))

    if ans == INF:
        print(-1)
    else:
        print(int(ans))

